import { existsSync } from "node:fs";
import { isAbsolute, normalize, resolve, sep } from "node:path";
import { pathToFileURL } from "node:url";
import type { QiyProject } from "./qiy-project";

export interface QiyGeneratorPluginContext {
  /** Parsed model IR. Treat as read-only. */
  project: Readonly<QiyProject>;
  appName: string;
  /** Files already generated by Qiy, keyed by workspace-relative path. */
  files: Readonly<Record<string, string>>;
}

export interface QiyGeneratorPlugin {
  name: string;
  version?: string;
  /** Return additional workspace-relative files. Existing generated files cannot be overwritten. */
  generate(context: QiyGeneratorPluginContext): Record<string, string> | void | Promise<Record<string, string> | void>;
}

function safePluginPath(root: string, value: string): string {
  if (typeof value !== "string" || value.trim() === "") throw new Error("Generator plugin path must be a non-empty string");
  if (isAbsolute(value)) throw new Error(`Generator plugin path must be relative to the project root: ${value}`);
  const absolute = resolve(root, value);
  const relative = normalize(absolute).slice(root.length).replace(/^[/\\]/, "");
  if (relative.startsWith("..") || relative.split(sep).includes("..")) throw new Error(`Generator plugin path escapes the project root: ${value}`);
  if (!existsSync(absolute)) throw new Error(`Generator plugin not found: ${value}`);
  return absolute;
}

export async function loadGeneratorPlugins(root: string, paths: readonly string[] = []): Promise<QiyGeneratorPlugin[]> {
  const plugins: QiyGeneratorPlugin[] = [];
  for (const value of paths) {
    const absolute = safePluginPath(root, value);
    const loaded = await import(`${pathToFileURL(absolute).href}?qiy=${Date.now()}`) as { default?: unknown };
    const plugin = loaded.default as QiyGeneratorPlugin | undefined;
    if (!plugin || typeof plugin !== "object" || typeof plugin.name !== "string" || typeof plugin.generate !== "function") {
      throw new Error(`Generator plugin ${value} must default-export { name, generate(context) }`);
    }
    if (plugins.some((item) => item.name === plugin.name)) throw new Error(`Duplicate generator plugin name: ${plugin.name}`);
    plugins.push(plugin);
  }
  return plugins;
}

/** Applies plugins after core generation. Plugin files are additive and path-checked. */
export async function applyGeneratorPlugins(
  files: Record<string, string>,
  project: QiyProject,
  appName: string,
  root: string,
  paths: readonly string[] = [],
): Promise<string[]> {
  if (paths.length === 0) return [];
  const plugins = await loadGeneratorPlugins(root, paths);
  const added: string[] = [];
  for (const plugin of plugins) {
    const output = await plugin.generate({ project, appName, files: { ...files } });
    if (output === undefined) continue;
    if (!output || typeof output !== "object" || Array.isArray(output)) throw new Error(`Generator plugin ${plugin.name} must return a record of file contents`);
    for (const [relativePath, content] of Object.entries(output)) {
      if (typeof content !== "string") throw new Error(`Generator plugin ${plugin.name} returned non-string content for ${relativePath}`);
      const normalized = normalize(relativePath).replace(/\\/g, "/");
      if (normalized.startsWith("/") || normalized.startsWith("../") || normalized.includes("/../") || normalized === "..") {
        throw new Error(`Generator plugin ${plugin.name} returned an unsafe path: ${relativePath}`);
      }
      if (Object.hasOwn(files, normalized)) {
        throw new Error(`Generator plugin ${plugin.name} cannot overwrite generated file ${normalized}; choose a distinct path`);
      }
      files[normalized] = content;
      added.push(normalized);
    }
  }
  return added;
}
